// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadDMSans = makeLoadFont('DMSans');
const loadSpaceMono = makeLoadFont('SpaceMono');

// Module-level font loading
const { fontFamily: dmSansFamily } = loadDMSans();
const { fontFamily: spaceMonoFamily } = loadSpaceMono();



export type PieChartStatisticProps = Record<string, any>;

const PieChartStatistic: React.FC<PieChartStatisticProps> = ({
  backgroundColor = "#0E100F",
  transparentBackground = false,
  durationInSeconds = 5,
  percentage = 66,
  pieColor = "#E979F9",
  pieBgColor = "#1E201F",
  textColorPrimary = "#FFFCE1",
  textColorAccent = "#E979F9",
  textColorMuted = "#B0AD96",
  line1 = "OF MARRIAGE PROBLEMS",
  line2 = "ARE UNRESOLVABLE.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parse background color for transparency safety
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // 1. Pie Chart Scale-in Animation (elastic snap)
  const pieIntroSpring = spring({
    frame: frame - 5,
    fps,
    config: { damping: 14, mass: 0.9, stiffness: 90 },
  });
  const pieScale = interpolate(pieIntroSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const pieRotation = interpolate(pieIntroSpring, [0, 1], [-25, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 2. Pie Segment Sweep Animation
  const sweepSpring = spring({
    frame: frame - 20,
    fps,
    config: { damping: 18, mass: 1.1, stiffness: 75 },
  });

  // Calculate dynamic circular sector variables
  const currentPercentage = interpolate(sweepSpring, [0, 1], [0, percentage], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Sector path helper to avoid Google Chrome stroke-rendering bugs with thick strokes
  const startAngle = -90;
  const sweepAngle = (currentPercentage / 100) * 360;
  const endAngle = startAngle + sweepAngle;

  const getWedgePath = (cx: number, cy: number, r: number, start: number, end: number) => {
    const startRad = (start * Math.PI) / 180;
    const endRad = (end * Math.PI) / 180;
    const x1 = cx + r * Math.cos(startRad);
    const y1 = cy + r * Math.sin(startRad);
    const x2 = cx + r * Math.cos(endRad);
    const y2 = cy + r * Math.sin(endRad);
    const largeArc = end - start > 180 ? 1 : 0;
    return `M ${cx} ${cy} L ${x1} ${y1} A ${r} ${r} 0 ${largeArc} 1 ${x2} ${y2} Z`;
  };

  const wedgePath = getWedgePath(50, 50, 50, startAngle, endAngle);

  // Dynamic white text positioning inside the pie segment
  // Positioned at the exact mathematical center of gravity of the wedge
  const midPercentage = currentPercentage / 2;
  const midAngle = (midPercentage / 100) * 360;
  const midAngleRad = (midAngle * Math.PI) / 180;
  const textD = 23; // radius distance from center
  const textX = 50 + textD * Math.sin(midAngleRad);
  const textY = 50 - textD * Math.cos(midAngleRad);

  // Inner text animation (delay to allow the sweep to start covering its location)
  const innerTextSpring = spring({
    frame: frame - 38,
    fps,
    config: { damping: 12, mass: 0.7, stiffness: 110 },
  });
  const innerTextScale = interpolate(innerTextSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const innerTextOpacity = interpolate(innerTextSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 3. Right Column huge stats animation
  const rightTitleSpring = spring({
    frame: frame - 30,
    fps,
    config: { damping: 15, mass: 0.8, stiffness: 100 },
  });
  const rightTitleY = interpolate(rightTitleSpring, [0, 1], [40, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const rightTitleOpacity = interpolate(rightTitleSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Counter animation for the right title percentage
  const animatedRightPercentage = Math.round(
    interpolate(rightTitleSpring, [0, 1], [0, percentage], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  // Staggered text lines entry
  const line1Spring = spring({
    frame: frame - 42,
    fps,
    config: { damping: 16, mass: 0.85, stiffness: 95 },
  });
  const line1X = interpolate(line1Spring, [0, 1], [-25, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const line1Opacity = interpolate(line1Spring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const line2Spring = spring({
    frame: frame - 49,
    fps,
    config: { damping: 16, mass: 0.85, stiffness: 95 },
  });
  const line2X = interpolate(line2Spring, [0, 1], [-25, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const line2Opacity = interpolate(line2Spring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Layout-specific sizes calculated relative to container aspect ratio
  const pieSize = Math.min(width, height) * 0.72;
  const leftColumnWidth = width * 0.5;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: dmSansFamily,
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "flex-start",
        padding: `0 ${width * 0.05}px`,
        overflow: "hidden",
      }}
    >
      {/* Left Column: Pie Chart Container */}
      <div
        style={{
          width: leftColumnWidth,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          height: "100%",
        }}
      >
        <div
          style={{
            width: pieSize,
            height: pieSize,
            transform: `scale(${pieScale}) rotate(${pieRotation}deg)`,
            transformOrigin: "center center",
            transition: "none",
          }}
        >
          <svg
            viewBox="0 0 100 100"
            style={{
              width: "100%",
              height: "100%",
              overflow: "visible",
            }}
          >
            <defs>
              <filter id="pink-glow" x="-20%" y="-20%" width="140%" height="140%">
                <feGaussianBlur stdDeviation="1.5" result="blur" />
                <feMerge>
                  <feMergeNode in="blur" />
                  <feMergeNode in="SourceGraphic" />
                </feMerge>
              </filter>
            </defs>

            {/* Background Grey Circle */}
            <circle
              cx="50"
              cy="50"
              r="50"
              fill={pieBgColor}
            />

            {/* Active Color Segment (drawn mathematically to prevent artifacts) */}
            {currentPercentage >= 99.9 ? (
              <circle
                cx="50"
                cy="50"
                r="50"
                fill={pieColor}
                filter="url(#pink-glow)"
              />
            ) : currentPercentage > 0 ? (
              <path
                d={wedgePath}
                fill={pieColor}
                filter="url(#pink-glow)"
              />
            ) : null}

            {/* Contrast-Rich Percentage Label Inside Pie Chart */}
            {percentage >= 15 && (
              <g
                transform={`translate(${textX}, ${textY}) scale(${innerTextScale}) translate(${-textX}, ${-textY})`}
                style={{
                  opacity: innerTextOpacity,
                  transition: "none",
                }}
              >
                <text
                  x={textX}
                  y={textY}
                  fontFamily={spaceMonoFamily}
                  fontWeight="bold"
                  fill="#0E100F"
                  fontSize="12.5"
                  textAnchor="middle"
                  dominantBaseline="central"
                  style={{
                    letterSpacing: "-0.04em",
                  }}
                >
                  {Math.round(currentPercentage)}%
                </text>
              </g>
            )}
          </svg>
        </div>
      </div>

      {/* Right Column: Dynamic Text Elements */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "flex-start",
          width: width * 0.4,
          paddingLeft: width * 0.02,
        }}
      >
        {/* Large Counter Number */}
        <h1
          style={{
            fontFamily: spaceMonoFamily,
            fontSize: height * 0.28,
            fontWeight: "bold",
            color: textColorAccent,
            lineHeight: 0.85,
            margin: 0,
            padding: 0,
            opacity: rightTitleOpacity,
            transform: `translateY(${rightTitleY}px)`,
            transition: "none",
            letterSpacing: "-0.05em",
          }}
        >
          {animatedRightPercentage}%
        </h1>

        {/* First Text Line */}
        <div
          style={{
            fontFamily: dmSansFamily,
            fontSize: height * 0.058,
            fontWeight: 800,
            color: textColorPrimary,
            lineHeight: 1.1,
            textTransform: "uppercase",
            opacity: line1Opacity,
            transform: `translateX(${line1X}px)`,
            marginTop: height * 0.02,
            transition: "none",
            letterSpacing: "-0.01em",
          }}
        >
          {line1}
        </div>

        {/* Second Text Line */}
        <div
          style={{
            fontFamily: dmSansFamily,
            fontSize: height * 0.058,
            fontWeight: 800,
            color: textColorMuted,
            lineHeight: 1.1,
            textTransform: "uppercase",
            opacity: line2Opacity,
            transform: `translateX(${line2X}px)`,
            marginTop: height * 0.005,
            transition: "none",
            letterSpacing: "-0.01em",
          }}
        >
          {line2}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PieChartStatistic;